xql_query:
// ============================================================
// Rule: CTX_Suspicious WScript to PowerShell to MSBuild Execution Chain
// Vendor: Cortex
// Objective:
// Detect activity associated with CTX_Suspicious WScript to PowerShell to MSBuild Execution Chain.
// Severity: SEV_040_HIGH
// Category: EVASION
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0005 - Defense Evasion
// Technique: T1127.001 - Trusted Developer Utilities Proxy Execution: MSBuild

// Title: CTX - Suspicious WScript to PowerShell to MSBuild Execution Chain
// Description: Detecta cadeia de execução wscript/cscript/mshta → powershell → msbuild.
// Esse padrão é raro em estações comuns e indica abuso de trusted developer utility (LOLBAS).
// MITRE ATT&CK: T1127.001 (MSBuild - Defense Evasion), T1059.001 (PowerShell), T1059.005 (VBScript)
//
// NOTA TH: A cadeia wscript→PS→MSBuild é clássica de ataques que usam MSBuild para executar
// código .NET inline (via arquivo .csproj ou .targets malicioso), evitando EDR focado em PE.
// Prioridade após disparo: localizar o arquivo de projeto MSBuild referenciado no command_line
// e extrair o conteúdo inline para análise. Verificar se há criação de processo filho por MSBuild.
//
// ALLOWLIST: Hosts de desenvolvimento e build servers com VS instalado devem ser excluídos.
// O filtro de TEMP no actor_cmd visa eliminar builds legítimos que não passam por diretórios temporários.
// mshta.exe foi intencionalmente incluído no causality: é vetor frequente de stage inicial via HTML App.

config case_sensitive = false
| dataset = xdr_data

| filter agent_os_type = ENUM.AGENT_OS_WINDOWS
| filter event_type = ENUM.PROCESS
    and event_sub_type = ENUM.PROCESS_START

| fields
    _time,
    agent_hostname,
    agent_ip_addresses,
    actor_effective_username,
    causality_actor_process_image_name,
    causality_actor_process_image_path,
    causality_actor_process_command_line,
    actor_process_image_name,
    actor_process_image_path,
    actor_process_command_line,
    action_process_image_name,
    action_process_image_path,
    action_process_image_command_line,
    action_process_image_sha256

| alter actor_cmd = lowercase(actor_process_command_line)
| alter action_cmd = lowercase(action_process_image_command_line)

// Filtro de cadeia: MSBuild como alvo final da execução
| filter action_process_image_name = "msbuild.exe"

// Parent imediato deve ser PowerShell — indica que PS foi o orquestrador do build malicioso
| filter actor_process_image_name in ("powershell.exe", "pwsh.exe")

// Avô (causality) deve ser engine de script — confirma origem da cadeia via script
// mshta.exe incluído: vetor HTML Application (.hta) é ponto de entrada comum
| filter causality_actor_process_image_name in ("wscript.exe", "cscript.exe", "mshta.exe")

// Contexto adicional: PowerShell operando em diretório temporário ou usando script nomeado como temp
// Nota: o filtro é OR — basta um dos dois para indicar comportamento anômalo
| filter actor_cmd ~= "(\\\\temp\\\\|c:\\\\temp\\\\|%temp%|\\\\appdata\\\\)"
    or actor_cmd ~= "ps_[a-z0-9_\\-]+\\.ps1"

| sort desc _time
